{
  "findings": [
    {
      "check_id": "CKV_AWS_3",
      "title": "EBS volume encryption is disabled",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "HIGH",
      "explanation": "The EBS volume explicitly sets encrypted to false, leaving data at rest unencrypted and potentially exposing sensitive data if the volume or a snapshot is compromised."
    }
  ],
  "patched_code": "resource \"aws_ebs_volume\" \"changeme_simple_aws_ebs_volume\" {\n  availability_zone = data.aws_availability_zones.changeme_available_az_list.names[0]\n  size              = 10\n  type              = \"standard\"\n  encrypted         = true\n}\n",
  "fix_summary": "Enabled encryption at rest for the EBS volume using the account's default EBS KMS key."
}
